        return

    if dc == 0:  # Vertical line
        if dr > 0:
            for t in range(dr + 1):
                points.append((r1 + t, c1))
        else:
            for t in range(-dr + 1):
                points.append((r1 - t, c1))
        return

    # General diagonal line
    g = gcd(abs(dr), abs(dc))
    if g == 1:
        # Simplified: step is (dr, dc) with no intermediate points
        if dr > 0:
            steps = dc if dc > 0 else -dc
            args = [(dr, dc)] if steps > 0 else [(dr, -dc)]
            pts = [(r1 + dr * t, c1 + dc * t) for t in range(0, steps + 1)]
        else:
